<main class="main-content"><div class="top-bar"><div><p class="eyebrow">EMPLOYEE WORKSPACE</p><h2 class="page-title">Operations overview</h2></div><div class="user-profile"><button id="themeToggleBtn" class="theme-toggle"><i class="fa-solid fa-moon"></i></button><b><?php echo htmlspecialchars($_SESSION['username']); ?></b></div></div><div class="welcome-banner"><h1>Keep every journey moving.</h1><p>Review booking state and the latest customer activity across DriveEase.</p></div><div class="stats-grid"><div class="stat-card"><span class="stat-label">Pending bookings</span><span class="stat-value" id="pendingBookings">—</span></div><div class="stat-card"><span class="stat-label">Open tickets</span><span class="stat-value" id="openTickets">—</span></div><div class="stat-card"><span class="stat-label">Customers</span><span class="stat-value" id="activeCustomers">—</span></div><div class="stat-card"><span class="stat-label">Fleet available</span><span class="stat-value" id="availableFleet">—</span></div></div><div class="content-grid employee-grid"><div class="card"><h3 class="card-title">Booking state</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Booking</th><th>Customer</th><th>Vehicle</th><th>Dates</th><th>Status</th></tr></thead><tbody id="bookings"><tr><td colspan="5" class="table-empty">Loading…</td></tr></tbody></table></div></div><div class="card"><h3 class="card-title">Customer activity</h3><ul class="activity-list" id="activity"><li class="activity-item table-empty">Loading…</li></ul></div></div></main><script>const e=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[x]));fetch('api/employee-dashboard.php').then(r=>r.json()).then(d=>{if(!d.success)throw 0;Object.entries(d.stats).forEach(([k,v])=>document.getElementById(k).textContent=v);document.getElementById('bookings').innerHTML=d.bookings.length?d.bookings.map(b=>`<tr><td>#${b.id}</td><td>${e(b.customer_name)}</td><td>${e(b.car_label